CREATE TABLE execution_technologies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,code varchar(80) NOT NULL,name varchar(300) NOT NULL,description varchar(3000),version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id));
CREATE TABLE execution_technology_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,technology_id uuid NOT NULL,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','review_required','approved','superseded')),execution_method varchar(1000) NOT NULL,required_layers jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(required_layers)='array'AND pg_column_size(required_layers)<=65536),thickness_mm numeric(12,4)CHECK(thickness_mm>0),drying_stages jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(drying_stages)='array'AND pg_column_size(drying_stages)<=65536),quality_rules jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(quality_rules)='array'AND pg_column_size(quality_rules)<=65536),inspection_requirements jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(inspection_requirements)='array'AND pg_column_size(inspection_requirements)<=65536),safety_notes jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(safety_notes)='array'AND pg_column_size(safety_notes)<=65536),approved_at timestamptz,approved_by uuid,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,technology_id,version_number),FOREIGN KEY(tenant_id,technology_id)REFERENCES execution_technologies(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id),CHECK((status='approved'AND approved_at IS NOT NULL AND approved_by IS NOT NULL)OR status<>'approved'));
CREATE TABLE work_scopes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,project_id uuid NOT NULL,code varchar(80) NOT NULL,name varchar(300) NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,project_id)REFERENCES projects(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id));
CREATE TABLE work_scope_revisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scope_id uuid NOT NULL,revision_number integer NOT NULL CHECK(revision_number>0),status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','review_required','ready_for_approval','approved','superseded','cancelled')),is_current boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1,approved_at timestamptz,approved_by uuid,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,scope_id,revision_number),FOREIGN KEY(tenant_id,scope_id)REFERENCES work_scopes(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id),CHECK((status='approved'AND approved_at IS NOT NULL AND approved_by IS NOT NULL)OR status<>'approved'));
CREATE UNIQUE INDEX uq_work_scope_current_revision ON work_scope_revisions(tenant_id,scope_id)WHERE is_current;
CREATE TABLE work_scope_scanner_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scope_id uuid NOT NULL,revision_id uuid NOT NULL,spatial_snapshot_id uuid NOT NULL,snapshot_fingerprint char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(tenant_id,revision_id,spatial_snapshot_id),FOREIGN KEY(tenant_id,scope_id)REFERENCES work_scopes(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,revision_id)REFERENCES work_scope_revisions(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,spatial_snapshot_id)REFERENCES approved_spatial_room_snapshots(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id));
CREATE TABLE work_scope_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scope_id uuid NOT NULL,revision_id uuid NOT NULL,work_type text NOT NULL CHECK(work_type IN('gypsum_plaster','cement_plaster','primer','painting','wallpaper','ceramic_tile','porcelain_tile','laminate','parquet','vinyl_flooring','epoxy_floor','drywall_wall','drywall_ceiling','concrete_repair','waterproofing','thermal_insulation','facade_render','facade_paint','electrical_chasing','pipe_installation','acoustic_insulation','cleaning','demolition','preparation')),description varchar(3000) NOT NULL,status text NOT NULL DEFAULT'planned'CHECK(status IN('planned','blocked','ready','completed','cancelled')),priority text NOT NULL DEFAULT'normal'CHECK(priority IN('low','normal','high','critical')),sequence integer NOT NULL CHECK(sequence BETWEEN 1 AND 10000),target_type text NOT NULL CHECK(target_type IN('project','building','building_floor','apartment','room','wall','ceiling','floor','door','window','opening','column','beam','custom_element')),target_reference varchar(300) NOT NULL,technology_version_id uuid NOT NULL,review_state text NOT NULL DEFAULT'pending'CHECK(review_state IN('pending','confirmed','rejected')),reviewed_at timestamptz,reviewed_by uuid,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,revision_id,sequence),FOREIGN KEY(tenant_id,scope_id)REFERENCES work_scopes(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,revision_id)REFERENCES work_scope_revisions(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,technology_version_id)REFERENCES execution_technology_versions(tenant_id,id),FOREIGN KEY(tenant_id,reviewed_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,updated_by)REFERENCES users(tenant_id,id));
CREATE TABLE work_scope_dependencies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scope_id uuid NOT NULL,revision_id uuid NOT NULL,predecessor_item_id uuid NOT NULL,successor_item_id uuid NOT NULL,dependency_kind text NOT NULL CHECK(dependency_kind IN('finish_to_start','drying','inspection','safety')),note varchar(2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(tenant_id,revision_id,predecessor_item_id,successor_item_id),FOREIGN KEY(tenant_id,scope_id)REFERENCES work_scopes(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,revision_id)REFERENCES work_scope_revisions(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,predecessor_item_id)REFERENCES work_scope_items(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,successor_item_id)REFERENCES work_scope_items(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id),CHECK(predecessor_item_id<>successor_item_id));
CREATE TABLE work_scope_quantity_mappings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scope_id uuid NOT NULL,revision_id uuid NOT NULL,work_item_id uuid NOT NULL,spatial_snapshot_id uuid NOT NULL,scanner_quantity_type varchar(160) NOT NULL,scanner_quantity_value numeric(20,8) NOT NULL CHECK(scanner_quantity_value>=0),scanner_unit text NOT NULL CHECK(scanner_unit IN('m','m2','m3','count')),scanner_formula_id varchar(160) NOT NULL,scanner_calculator_version varchar(80) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL,UNIQUE(tenant_id,work_item_id,spatial_snapshot_id,scanner_quantity_type),FOREIGN KEY(tenant_id,scope_id)REFERENCES work_scopes(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,revision_id)REFERENCES work_scope_revisions(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,work_item_id)REFERENCES work_scope_items(tenant_id,id)ON DELETE CASCADE,FOREIGN KEY(tenant_id,spatial_snapshot_id)REFERENCES approved_spatial_room_snapshots(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES users(tenant_id,id));
CREATE TABLE approved_work_scope_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,scope_id uuid NOT NULL,revision_id uuid NOT NULL,revision_number integer NOT NULL,project_id uuid NOT NULL,content jsonb NOT NULL CHECK(jsonb_typeof(content)='object'AND pg_column_size(content)<=4194304),content_fingerprint char(64) NOT NULL,schema_version varchar(40) NOT NULL DEFAULT'work-scope-v1',approved_at timestamptz NOT NULL DEFAULT now(),approved_by uuid NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,revision_id),FOREIGN KEY(tenant_id,scope_id)REFERENCES work_scopes(tenant_id,id),FOREIGN KEY(tenant_id,revision_id)REFERENCES work_scope_revisions(tenant_id,id),FOREIGN KEY(tenant_id,project_id)REFERENCES projects(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES users(tenant_id,id));
CREATE FUNCTION protect_approved_work_scope_snapshot()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'APPROVED_WORK_SCOPE_SNAPSHOT_IMMUTABLE';END$$;CREATE TRIGGER immutable_approved_work_scope_snapshot BEFORE UPDATE OR DELETE ON approved_work_scope_snapshots FOR EACH ROW EXECUTE FUNCTION protect_approved_work_scope_snapshot();
CREATE FUNCTION protect_approved_work_scope_content()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE rid uuid;state text;BEGIN rid=CASE WHEN TG_OP='DELETE'THEN OLD.revision_id ELSE NEW.revision_id END;SELECT status INTO state FROM work_scope_revisions WHERE id=rid;if state IN('approved','superseded')THEN RAISE EXCEPTION'APPROVED_WORK_SCOPE_IMMUTABLE';END IF;IF TG_OP='DELETE'THEN RETURN OLD;END IF;RETURN NEW;END$$;
CREATE TRIGGER immutable_scope_sources BEFORE INSERT OR UPDATE OR DELETE ON work_scope_scanner_sources FOR EACH ROW EXECUTE FUNCTION protect_approved_work_scope_content();CREATE TRIGGER immutable_scope_items BEFORE INSERT OR UPDATE OR DELETE ON work_scope_items FOR EACH ROW EXECUTE FUNCTION protect_approved_work_scope_content();CREATE TRIGGER immutable_scope_dependencies BEFORE INSERT OR UPDATE OR DELETE ON work_scope_dependencies FOR EACH ROW EXECUTE FUNCTION protect_approved_work_scope_content();CREATE TRIGGER immutable_scope_mappings BEFORE INSERT OR UPDATE OR DELETE ON work_scope_quantity_mappings FOR EACH ROW EXECUTE FUNCTION protect_approved_work_scope_content();
CREATE FUNCTION protect_approved_technology()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.status IN('approved','superseded')THEN RAISE EXCEPTION'APPROVED_TECHNOLOGY_IMMUTABLE';END IF;RETURN CASE WHEN TG_OP='DELETE'THEN OLD ELSE NEW END;END$$;CREATE TRIGGER immutable_approved_technology BEFORE UPDATE OR DELETE ON execution_technology_versions FOR EACH ROW EXECUTE FUNCTION protect_approved_technology();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['execution_technologies','execution_technology_versions','work_scopes','work_scope_revisions','work_scope_scanner_sources','work_scope_items','work_scope_dependencies','work_scope_quantity_mappings','approved_work_scope_snapshots']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_%I ON %I USING(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid)',t,t);END LOOP;END$$;
CREATE INDEX idx_scope_project ON work_scopes(tenant_id,project_id,updated_at DESC);CREATE INDEX idx_scope_items_revision ON work_scope_items(tenant_id,revision_id,sequence);CREATE INDEX idx_scope_mapping_item ON work_scope_quantity_mappings(tenant_id,work_item_id);CREATE INDEX idx_technology_versions ON execution_technology_versions(tenant_id,technology_id,version_number DESC);
INSERT INTO permissions(code,description)VALUES('work_scopes.create','Create work scopes'),('work_scopes.read','Read work scopes and technologies'),('work_scopes.edit','Edit work scopes and technologies'),('work_scopes.review','Review work scope intent and sequence'),('work_scopes.approve','Approve technologies and work scopes'),('work_scopes.snapshots.read','Read approved work scope snapshots')ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE(r.code IN('tenant_admin','project_manager')AND p.code LIKE'work_scopes.%')OR(r.code='employee'AND p.code IN('work_scopes.create','work_scopes.read','work_scopes.edit','work_scopes.review'))OR(r.code='read_only'AND p.code IN('work_scopes.read','work_scopes.snapshots.read'))ON CONFLICT DO NOTHING;
